{"cmd":"python3 - <<'PY'
import json, pathlib, collections, re
root=pathlib.Path('/Users/thomi/.local/share/entire/brain/gh/entireio/cli')
manifest=json.loads((root/'manifest.json').read_text())
sessions=(manifest.get('sources',{}).get('sessions',{}).get('sessions') or manifest.get('sessions') or [])
# Inspect up to 100 recent sessions for event/tool shapes, without printing content.
paths=[]
for s in sessions[-100:]:
    p=root/s.get('transcript_path','')
    if p.exists(): paths.append(p)
type_counts=collections.Counter(); role_counts=collections.Counter(); key_counts=collections.Counter(); tool_names=collections.Counter(); command_heads=collections.Counter()
lines=0; files=0
for p in paths:
    files+=1
    for line in p.open(errors='ignore'):
        lines+=1
        try: obj=json.loads(line)
        except Exception: continue
        for k in obj.keys(): key_counts[k]+=1
        for k in ('type','event'):
            if isinstance(obj.get(k), str): type_counts[obj[k]]+=1
        if isinstance(obj.get('role'), str): role_counts[obj['role']]+=1
        # Generic tool-call extraction patterns.
        for key in ('tool','name'):
            if isinstance(obj.get(key), str): tool_names[obj[key]]+=1
        msg=obj.get('message')
        if isinstance(msg, dict):
            if isinstance(msg.get('role'), str): role_counts[msg['role']]+=1
            content=msg.get('content')
            if isinstance(content, list):
                for part in content:
                    if isinstance(part, dict):
                        if part.get('type') in ('tool_use','tool_result'): tool_names[part.get('name') or part.get('type')]+=1
                        inp=part.get('input')
                        if isinstance(inp, dict):
                            cmd=inp.get('cmd') or inp.get('command')
                            if isinstance(cmd, str): command_heads[cmd.strip().split()[0] if cmd.strip() else '']+=1
        if isinstance(obj.get('content'), list):
            for part in obj['content']:
                if isinstance(part, dict) and part.get('type') in ('tool_use','tool_result'):
                    tool_names[part.get('name') or part.get('type')]+=1
print('files_sampled', files, 'lines', lines)
print('top keys', key_counts.most_common(20))
print('types/events', type_counts.most_common(20))
print('roles', role_counts.most_common(10))
print('tool names', tool_names.most_common(20))
print('command heads', command_heads.most_common(20))
PY","workdir":"/Users/thomi/Projects/entire-brain","yield_time_ms":1000,"max_output_tokens":12000}

